import {shuffle,createSession,recordAnswer,advance,firstAttemptScore,updateProgress} from './engine.mjs';
const root=document.querySelector('#app');
const SECTION=['','Основы безопасности','Архитектура Android','Угрозы и онтологии','Аутентификация и доступ','Хранение и криптография','Cloud и secure coding'];
const LECTURE=['','1','2','3–4','5','6','7'];
const KEY='midterm-lab-v1';let warning='',data,view='home',setupMode='practice',filter='all',search='',flashIndex=0,flashFlip=false,flashIds=[],historyIndex=null;
let state={progress:{},session:null,exams:[],settings:{section:'all',shuffle:true}};
try{const raw=localStorage.getItem(KEY);if(raw){const saved=JSON.parse(raw);if(saved&&typeof saved.progress==='object'&&!Array.isArray(saved.progress)){state={...state,...saved};state.settings={section:'all',shuffle:true,...saved.settings};state.exams=Array.isArray(saved.exams)?saved.exams:[]}}}catch{warning='Не удалось прочитать сохранение. Можно продолжать; прогресс текущего сеанса будет в памяти.'}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{warning='Браузер не разрешил сохранение. Не закрывайте вкладку, чтобы не потерять текущий прогресс.'}}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const byId=id=>data.find(q=>q.id===id);
const pct=(n,d)=>d?Math.round(n/d*100):0;
const btn=(text,action,cl='')=>`<button class="btn ${cl}" data-action="${action}">${text}</button>`;
function shell(body,active='home'){root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brandmark">▧</span>midterm<span style="color:#8a9776">lab</span></div><div class="subtitle">MOBILE SECURITY · 01—07</div><nav class="nav" aria-label="Главная навигация">${[['home','⌂','Обзор'],['practice','◈','Практика'],['flashcards','▤','Карточки'],['bank','☷','Все вопросы']].map(([id,icon,label])=>`<button class="${active===id?'active':''}" data-nav="${id}"><i>${icon}</i>${label}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="mini-icon">♧ <span>Шаг за шагом.<br>Вопрос за вопросом.</span></div>Прогресс хранится в этом браузере.<br>Без аккаунта и регистрации.</div></aside><main class="main"><header class="topbar"><span>Твоя подготовка <span style="margin:0 9px;color:#c1c7b7">/</span> <strong>Mobile Security</strong></span><span class="pill"><span class="dot"></span> Лекции 1–7</span></header>${warning?`<p class="storage-warning">${esc(warning)}</p>`:''}${body}<footer class="footer"><span>Составлено по лекциям · 67 вопросов из sample<br>Варианты ответов подготовлены для тренировки.</span><span>Учись понимать, а не угадывать.<br><button class="action-link" data-action="settings">Данные и настройки</button></span></footer></main></div>`;bind()}
function home(){const mastered=data.filter(q=>state.progress[q.id]?.mastered).length;const attempted=Object.values(state.progress).reduce((s,p)=>s+p.attempts,0);const correct=Object.values(state.progress).reduce((s,p)=>s+p.correct,0);const session=state.session; shell(`<section class="hero"><div><div class="eyebrow">ТВОЙ СПОКОЙНЫЙ ПЛАН НА MIDTERM</div><h1>Разберись. Запомни.<br><span style="color:#7a8a64">Сдай уверенно.</span></h1><p>Всё из лекций 1–7 в одном месте. Практикуйся, разбирай<br class="desktop"> ошибки и возвращайся к тому, что ещё не запомнилось.</p></div><div class="hero-art" aria-hidden="true"><div class="art-card"></div><div class="art-card front">✓</div><div class="art-star">✧</div></div></section>${session&&!session.done?`<div class="resume row space"><span>Есть незавершённая сессия · ${session.index+1} / ${session.queue.length}</span>${btn('Продолжить →','resume','secondary')}</div>`:''}<div class="stats"><div class="stat"><div class="stat-label">ВОПРОСОВ В БАЗЕ <span>▤</span></div><strong>67</strong><small>все вопросы из sample</small></div><div class="stat"><div class="stat-label">ИЗУЧЕНО <span>✓</span></div><strong class="green">${mastered}<span style="font-size:14px;color:#b0b7a5;font-weight:500"> / 67</span></strong><small>${pct(mastered,67)}% программы пройдено</small></div><div class="stat"><div class="stat-label">ПОВТОРОВ В СЕССИИ <span>↻</span></div><strong>${session&&!session.done?session.queue.slice(session.index+1).filter(id=>session.answers.some(a=>a.id===id&&!a.correct)).length:0}</strong><small>возвращаются прямо в квизе</small></div><div class="stat"><div class="stat-label">ТОЧНОСТЬ <span>◎</span></div><strong>${attempted?pct(correct,attempted)+'%':'—'}</strong><small>${attempted?attempted+' ответов за всё время':'начнём с первого вопроса'}</small></div></div><div class="dashboard-grid"><section><h2 class="section-label">Как будем готовиться? <small>В своём темпе</small></h2><div class="modes"><button class="mode featured" data-nav="practice"><span class="mode-icon">◈</span><span class="arrow">↗</span><h3>Умная практика</h3><p>Ошибся? Вопрос вернётся через два<br>других. Закрепляй сложное сразу.</p><span class="tag">НАЧНИ ЗДЕСЬ</span></button><button class="mode" data-nav="exam"><span class="mode-icon">◷</span><span class="arrow">↗</span><h3>Пробный экзамен</h3><p>Без подсказок и повторов.<br>Результаты и разбор — в конце.</p></button><button class="mode" data-nav="flashcards"><span class="mode-icon">▤</span><span class="arrow">↗</span><h3>Карточки</h3><p>Вспомни ответ самостоятельно.<br>Переверни и проверь себя.</p></button><button class="mode" data-nav="bank"><span class="mode-icon">☷</span><span class="arrow">↗</span><h3>Вопросы с объяснениями</h3><p>Все вопросы, ответы и слайды.<br>Разберись в сложной теме.</p></button></div><div class="below"><span style="font-size:21px;color:#9baa86">✧</span><span><strong>Не запоминай букву ответа.</strong><br>Варианты перемешиваются при каждом показе вопроса.</span></div></section><aside class="panel"><h3>Твой маршрут по лекциям</h3><div class="topic-list">${SECTION.slice(1).map((s,i)=>{const qs=data.filter(q=>q.section===i+1),n=qs.filter(q=>state.progress[q.id]?.mastered).length;return `<div class="topic"><span class="n">${LECTURE[i+1].padStart(2,'0')}</span><div><strong>${s}</strong><div class="track"><span style="width:${pct(n,qs.length)}%"></span></div></div><small>${n}/${qs.length}</small></div>`}).join('')}</div><div class="tip"><strong>↳ Маленький совет</strong>После ошибки прочитай объяснение: так следующий ответ будет осознанным.</div></aside></div>`) }
function setup(mode){setupMode=mode;view='setup';const label=mode==='exam'?'Пробный экзамен':'Умная практика';shell(`<div class="pagehead"><div class="eyebrow">ВЫБЕРИ СВОЙ РИТМ</div><h1>${label}</h1><p>${mode==='exam'?'Один ответ на вопрос. Правильные ответы и объяснения увидишь после завершения.':'После ошибки вопрос возвращается через два других; в конце очереди — раньше. Повторяется до правильного ответа.'}</p></div><div class="setup"><section class="panel"><label class="field">Раздел<select id="section"><option value="all">Все лекции · 67 вопросов</option>${SECTION.slice(1).map((s,i)=>`<option value="${i+1}" ${state.settings.section===String(i+1)?'selected':''}>Лекция ${LECTURE[i+1]} · ${s}</option>`).join('')}</select></label><label class="check"><input id="shuffle" type="checkbox" ${state.settings.shuffle?'checked':''}> Перемешивать вопросы</label><p class="hint">Варианты ответов перемешиваются всегда. </p><p id="selected-count" class="hint"></p>${btn('Начать →','start')} ${state.session&&!state.session.done?btn('Продолжить текущую','resume','ghost'):''}</section><div class="hint">Вопросы сохранены на английском, как в sample. Объяснения — на русском. Формулировки вариантов созданы для тренировки и могут отличаться от реального теста.</div></div>`,mode==='exam'?'practice':mode);updateCount()}
function selection(){const sec=document.querySelector('#section')?.value||state.settings.section;return data.filter(q=>(sec==='all'||String(q.section)===sec))}
function updateCount(){const el=document.querySelector('#selected-count');if(el){const n=selection().length;el.textContent=`В этой сессии: ${n} вопросов`;document.querySelector('[data-action=start]').disabled=!n}}
function start(){const qs=selection();if(!qs.length)return;state.settings={section:document.querySelector('#section').value,shuffle:document.querySelector('#shuffle').checked};state.session=createSession(qs.map(q=>q.id),{mode:setupMode==='exam'?'exam':'practice',random:state.settings.shuffle});state.session.sourceMode=setupMode;save();historyIndex=null;view='quiz';render()}
function evidence(q){return `<div class="source">${q.sources.map(s=>`${esc(s.file)} · слайд${s.slides.length>1?'ы':''} ${s.slides.join(', ')}`).join(' · ')}</div>${q.note?`<p class="note">${esc(q.note)}</p>`:''}${q.external?`<a class="source" href="${esc(q.external)}" target="_blank" rel="noopener noreferrer">Дополнительный источник ↗</a>`:''}<details><summary>Посмотреть текст слайдов</summary>${q.evidence.map(e=>`<pre><b>${esc(e.file)} · ${e.slide}</b>\n${esc(e.text)}</pre>`).join('')}</details>`}
function explain(q){return `<p>${esc(q.explanation)}</p>${evidence(q)}`}
function quiz(){const s=state.session;if(!s){home();return}if(s.done){result();return}const reviewing=historyIndex!==null;const past=reviewing?s.answers[historyIndex]:null;const q=byId(reviewing?past.id:s.queue[s.index]);if(!q){state.session=null;save();home();return}if(!s.options.length&&!reviewing){s.options=shuffle(q.options.map(o=>o.id));save()}const current=reviewing?past:s.current;const reveal=current&&s.mode!=='exam';const options=reviewing?q.options.map(o=>o.id):s.options;const unique=new Set(s.answers.map(a=>a.id)).size;const isRepeat=s.answers.some(a=>a.id===q.id)&&!s.current&&!reviewing;shell(`<div class="quiz"><div class="row space"><button class="action-link" data-nav="home">← Сохранить и выйти</button><span class="hint">${s.mode==='exam'?'Экзамен':'Практика'} · ${unique} / ${s.total} вопросов</span></div><div class="progress"><span style="width:${pct(unique,s.total)}%"></span></div><section class="question-card"><div class="question-meta"><span class="pill">Лекция ${LECTURE[q.section]}</span><span>Sample №${q.number} · ${SECTION[q.section]}</span>${isRepeat?'<span class="pill">↻ Закрепление</span>':''}${reviewing?'<span class="pill">История ответов</span>':''}</div><h2>${esc(q.question)}</h2><div class="options">${options.map((id,i)=>{const o=q.options.find(o=>o.id===id);return `<button class="option ${reveal&&o.id===q.correct?'correct':''} ${reveal&&o.id===current.choice&&!current.correct?'wrong':''} ${current&&!reveal&&o.id===current.choice?'selected':''}" data-choice="${o.id}" ${current||reviewing?'disabled':''}><span class="letter">${i+1}</span><span>${esc(o.text)}</span>${reveal&&o.id===q.correct?'<span style="margin-left:auto">✓</span>':''}</button>`}).join('')}</div>${reveal?`<div class="feedback ${current.correct?'':'wrong'}" role="status"><strong>${current.correct?'✓ Верно. Так держать.':'↻ Не совсем. Разберёмся.'}</strong>${!current.correct?`<p>Правильный ответ: <b>${esc(q.options.find(o=>o.id===q.correct).text)}</b></p>`:''}${explain(q)}${!current.correct&&!reviewing?'<p class="hint">Этот вопрос добавлен на повтор через два других (или раньше в конце сессии).</p>':''}</div>`:current?'<div class="feedback" role="status">Ответ сохранён. Разбор будет после завершения экзамена.</div>':''}<div class="quiz-bottom">${reviewing?btn('К текущему вопросу →','back-current','secondary'):`<button class="btn ghost" data-action="previous" ${s.answers.length-(s.current?1:0)<1?'disabled':''}>← Ревью предыдущего</button>`}<span class="kbd">1–4 — ответ · Enter — дальше</span>${!reviewing&&current?btn(s.index===s.queue.length-1?'Завершить ✓':'Дальше →','next'):''}</div></section>${s.mode==='exam'?'<p class="hint" style="margin-top:16px">Возврат к прошлому вопросу показывает выбранный ответ. Изменять отправленные ответы нельзя.</p>':''}</div>`,'practice')}
function answer(choice){if(view!=='quiz'||historyIndex!==null)return;const s=state.session,q=byId(s.queue[s.index]);if(!q.options.some(o=>o.id===choice))return;if(recordAnswer(s,q,choice)){if(s.mode!=='exam')state.progress=updateProgress(state.progress,q.id,choice===q.correct);save();render();document.querySelector('.feedback')?.scrollIntoView({behavior:'smooth',block:'nearest'})}}
function next(){const s=state.session;if(!advance(s))return;if(s.done){if(s.mode==='exam'){s.answers.forEach(a=>state.progress=updateProgress(state.progress,a.id,a.correct));state.exams.unshift({date:Date.now(),...firstAttemptScore(s.answers)});state.exams=state.exams.slice(0,20)}s.finishedAt=Date.now()}save();render();window.scrollTo({top:0,behavior:'instant'})}
function result(){const s=state.session;const score=firstAttemptScore(s.answers);shell(`<div class="pagehead"><div class="eyebrow">СЕССИЯ ЗАВЕРШЕНА</div><h1>${s.mode==='exam'?'Результаты экзамена':'Ещё один шаг вперёд.'}</h1></div><section class="panel result"><div class="hint">Точность первой попытки</div><div class="score">${pct(score.correct,score.total)}<span style="font-size:30px">%</span></div><p>${score.correct} из ${score.total} с первого раза · Всего ответов: ${s.answers.length}</p><p class="hint">${s.mode==='practice'?'Повторные попытки не повышают оценку первой попытки. Все вопросы этой сессии закреплены правильным ответом.':'Ниже — полный разбор ответов. В умной практике неверные ответы повторяются автоматически.'}</p><div class="row" style="justify-content:center">${btn('На главную','home')}${btn('Ещё раз','restart','ghost')}</div></section><div class="list">${s.answers.filter((a,i,all)=>all.findIndex(x=>x.id===a.id)===i).map(a=>{const q=byId(a.id);return `<details class="bank-item"><summary><span style="color:${a.correct?'#6f8755':'#b5745c'}">${a.correct?'✓':'↻'}</span> ${esc(q.question)}</summary><div class="review-row"><p class="${a.correct?'good':'bad'}">Твой первый ответ: ${esc(q.options.find(o=>o.id===a.choice)?.text)}</p><p class="good">Правильный: ${esc(q.options.find(o=>o.id===q.correct).text)}</p>${explain(q)}</div></details>`}).join('')}</div>`,'practice')}
function bankItem(q){return `<article class="bank-item"><div class="question-meta">Лекция ${LECTURE[q.section]} · Sample №${q.number}${q.note?' · Есть уточнение':''}</div><h3>${esc(q.question)}</h3><details><summary>Ответ и объяснение</summary><p style="margin-top:15px"><b>${esc(q.options.find(o=>o.id===q.correct).text)}</b></p>${explain(q)}</details></article>`}
function filters(){return `<div class="filters"><input class="search" id="search" type="search" placeholder="Найти вопрос или термин…" value="${esc(search)}" aria-label="Поиск вопросов"><select class="search" id="filter" aria-label="Фильтр раздела"><option value="all">Все лекции</option>${SECTION.slice(1).map((s,i)=>`<option value="${i+1}" ${filter===String(i+1)?'selected':''}>Лекция ${LECTURE[i+1]} · ${s}</option>`).join('')}</select></div>`}
function filtered(){return data.filter(q=>(filter==='all'||String(q.section)===filter)&&`${q.question} ${q.explanation} ${q.options.map(o=>o.text).join(' ')}`.toLowerCase().includes(search.toLowerCase()))}
function bank(){shell(`<div class="pagehead"><div class="eyebrow">ПОЛНАЯ БАЗА</div><h1>Все 67 вопросов</h1><p>Оригинальные формулировки из sample, ответы, объяснения и текст соответствующих слайдов.</p></div>${filters()}<div id="bank-list" class="list">${filtered().map(bankItem).join('')}</div>`,'bank')}
function flashcards(reset=false){if(reset||!flashIds.length){flashIds=filtered().map(q=>q.id);flashIndex=0;flashFlip=false}const q=byId(flashIds[flashIndex]);shell(`<div class="pagehead"><div class="eyebrow">СНАЧАЛА ВСПОМНИ САМ</div><h1>Карточки</h1><p>Проговори ответ до переворота. Самооценка карточки не меняет статистику тестов.</p></div>${filters()}<div class="quiz"><div class="row space"><span class="hint">${q?flashIndex+1:0} / ${flashIds.length}</span><button class="action-link" data-action="shuffle-flash">⇄ Перемешать</button></div>${q?`<button class="flash" data-action="flip" aria-label="Перевернуть карточку"><div class="eyebrow">${flashFlip?'ОТВЕТ':'ВОПРОС'} · ЛЕКЦИЯ ${LECTURE[q.section]}</div><h2>${esc(flashFlip?q.options.find(o=>o.id===q.correct).text:q.question)}</h2>${flashFlip?`<p>${esc(q.explanation)}</p>`:''}<span class="hint">Нажми, чтобы перевернуть · Space</span></button>${flashFlip?`<div class="panel" style="margin-top:15px">${evidence(q)}</div>`:''}<div class="flash-controls">${btn('← Назад','flash-prev','ghost')}${btn('Ещё повторить','flash-again','secondary')}${btn('Знаю →','flash-next')}</div>`:'<div class="empty">По этому запросу карточек нет.</div>'}</div>`,'flashcards')}
function settings(){shell(`<div class="pagehead"><h1>Данные и настройки</h1><p>Прогресс хранится только в этом браузере и не синхронизируется между устройствами.</p></div><div class="setup"><section class="panel"><h3>Резервная копия прогресса</h3><p class="hint">Скачай JSON и перенеси его на другое устройство через импорт.</p><div class="row">${btn('Экспорт прогресса','export','secondary')}<label class="btn ghost">Импорт<input type="file" id="import" accept="application/json,.json" hidden></label></div></section><section class="panel"><h3>О материалах</h3><p class="hint">Все 67 вопросов из midterm_sample questions.docx сохранены. В исходнике нет ответов и вариантов. Варианты созданы для тренировки; это не официальный ключ преподавателя. Файлы lecture 3.pptx и lecture 3-4.pptx содержат одинаковые 20 слайдов. Пропущенные номера в sample сохранены.</p><p class="hint">Ответы сверены по семи презентациям. Уточнения отдельно отмечены у вопросов про nation-state actors, vishing, static analysis, pinning и SPARQL. Три состояния данных дополнены по лекции 7.</p></section><section class="panel"><h3>История экзаменов</h3>${state.exams.length?state.exams.map(e=>`<p class="history-summary">${new Date(e.date).toLocaleString('ru-RU')} · ${e.correct}/${e.total} · ${pct(e.correct,e.total)}%</p>`).join(''):'<p class="hint">Пока нет завершённых экзаменов.</p>'}</section><section class="panel"><h3>Начать с чистого листа</h3><p class="hint">Удалит прогресс, историю и текущую сессию из этого браузера.</p>${btn('Сбросить прогресс','reset','danger')}</section></div>`)}
function navigate(v){historyIndex=null;window.scrollTo(0,0);if(['practice','exam'].includes(v)){setup(v);return}view=v;if(v==='flashcards')flashIds=[];render()}
function render(){if(view==='home')home();else if(view==='quiz')quiz();else if(view==='bank')bank();else if(view==='flashcards')flashcards();else if(view==='settings')settings();else setup(setupMode)}
function act(a){if(a==='start')start();else if(a==='resume'){view='quiz';historyIndex=null;render()}else if(a==='next')next();else if(a==='previous'){const s=state.session;historyIndex=historyIndex===null?s.answers.length-1-(s.current?1:0):Math.max(0,historyIndex-1);render()}else if(a==='back-current'){historyIndex=null;render()}else if(a==='home')navigate('home');else if(a==='practice')navigate('practice');else if(a==='settings')navigate('settings');else if(a==='restart'){setup(state.session?.sourceMode||'practice')}else if(a==='flip'){flashFlip=!flashFlip;render()}else if(a==='flash-prev'){flashIndex=Math.max(0,flashIndex-1);flashFlip=false;render()}else if(a==='flash-next'){flashIndex=(flashIndex+1)%flashIds.length;flashFlip=false;render()}else if(a==='flash-again'){const id=flashIds[flashIndex];flashIds.splice(flashIndex,1);flashIds.push(id);flashIndex=Math.min(flashIndex,flashIds.length-1);flashFlip=false;render()}else if(a==='shuffle-flash'){flashIds=shuffle(flashIds);flashIndex=0;flashFlip=false;render()}else if(a==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify({version:1,...state},null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='midterm-progress.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}else if(a==='reset'){if(confirm('Удалить весь прогресс? Сначала можно сделать экспорт.')){state={progress:{},session:null,exams:[],settings:{section:'all',shuffle:true}};save();navigate('home')}}}
function bind(){document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>navigate(el.dataset.nav));document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>act(el.dataset.action));document.querySelectorAll('[data-choice]').forEach(el=>el.onclick=()=>answer(el.dataset.choice));document.querySelector('#section')?.addEventListener('change',updateCount);document.querySelector('#search')?.addEventListener('input',e=>{search=e.target.value;if(view==='bank'){document.querySelector('#bank-list').innerHTML=filtered().map(bankItem).join('')}else{flashIds=filtered().map(q=>q.id);flashIndex=0;flashFlip=false;const pos=e.target.selectionStart;flashcards();const input=document.querySelector('#search');input.focus();input.setSelectionRange(pos,pos)}});document.querySelector('#filter')?.addEventListener('change',e=>{filter=e.target.value;if(view==='flashcards')flashIds=[];render()});document.querySelector('#import')?.addEventListener('change',async e=>{try{const raw=JSON.parse(await e.target.files[0].text());if(raw.version!==1||!raw.progress||typeof raw.progress!=='object'||Array.isArray(raw.progress))throw Error();const progress={};for(const q of data){const p=raw.progress[q.id];if(p){if(!['attempts','correct','wrong','streak'].every(k=>Number.isSafeInteger(p[k])&&p[k]>=0)||p.correct+p.wrong!==p.attempts||typeof p.lastCorrect!=='boolean')throw Error();progress[q.id]={attempts:p.attempts,correct:p.correct,wrong:p.wrong,streak:p.streak,lastCorrect:p.lastCorrect,mastered:p.lastCorrect}}}state.progress=progress;state.session=null;state.exams=Array.isArray(raw.exams)?raw.exams.filter(x=>Number.isFinite(x.date)&&Number.isInteger(x.correct)&&Number.isInteger(x.total)&&x.correct>=0&&x.total>0&&x.correct<=x.total).slice(0,20):[];save();navigate('home')}catch{alert('Не удалось импортировать файл. Нужен корректный экспорт прогресса Midterm Lab.')}})}
document.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||e.ctrlKey||e.altKey||e.metaKey||e.repeat)return;if(view==='quiz'&&historyIndex===null){const s=state.session;if(!s||s.done)return;if(/^[1-4]$/.test(e.key)&&!s.current){e.preventDefault();answer(s.options[Number(e.key)-1])}if(e.key==='Enter'&&s.current&&e.target.tagName!=='BUTTON'){e.preventDefault();next()}}if(view==='flashcards'&&e.code==='Space'&&e.target.tagName!=='BUTTON'){e.preventDefault();act('flip')}});
try{const response=await fetch('questions.json');if(!response.ok)throw Error();data=await response.json();if(state.session&&(!Array.isArray(state.session.queue)||!state.session.queue.every(id=>byId(id))||!Number.isInteger(state.session.index)||state.session.index<0||!Array.isArray(state.session.answers)||!Array.isArray(state.session.options))){state.session=null}render()}catch{root.innerHTML='<p class="loading">Не удалось загрузить вопросы. Проверь подключение и обнови страницу.</p>'}

if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js').catch(()=>{})}
